const highExposure = new Set(['software-engineer','data-analyst','management-consultant','digital-marketer','market-researcher','brand-content-strategist','visual-designer','video-producer','technical-writer','financial-analyst','accountant','business-analyst']);
const physical = new Set(['renewable-energy-technician','industrial-automation-technician','robotics-integration-specialist','grid-intelligence-analyst','digital-twin-specialist','culinary-food-operations','building-systems-technician','construction-site-coordinator','precision-agriculture-technician','warehouse-logistics-supervisor','fleet-service-technician','repair-craft-business']);
const humanCentred = new Set(['teacher-learning-designer','career-development-practitioner','psychologist-counsellor','public-health-manager','healthcare-operations','social-impact-manager','social-worker-case-coordinator','digital-health-ai-specialist','climate-adaptation-planner','nursing-allied-health','community-care-worker','early-childhood-educator','hospitality-guest-operations','retail-merchandising-operations','emergency-response-professional']);

export function getAITransition(role:CareerRole):AITransition {
  const isNative = futureCareerRoles.some((item)=>item.id===role.id) && !humanCentred.has(role.id) && !physical.has(role.id);
  const delegates = delegatedByRole[role.id] ?? (isNative ? 'Automate routine generation, monitoring and first-pass analysis inside the system.' : role.aiShift);
  const humanLeverage = humanByRole[role.id] ?? (humanCentred.has(role.id) ? 'Context, relationships, ethics, safety and accountable decisions in the real world.' : physical.has(role.id) ? 'Physical-world validity, safety, integration and responsibility for consequences.' : 'Problem framing, verification, domain judgment and accountability for outcomes.');
  return {
    position:isNative?'AI-native':humanCentred.has(role.id)?'Human-centred + AI':physical.has(role.id)?'Physical-world + AI':'AI-reinvented',
    exposure:highExposure.has(role.id)?'High task change':physical.has(role.id)||humanCentred.has(role.id)?'Lower direct automation':'Moderate task change',
    delegates,
    humanLeverage,
    prepare:[role.skills.aiDigital[0],role.skills.roleSpecific[0],role.skills.transferable[0]].filter(Boolean),
    adjacentTitles:role.id==='software-engineer'?['AI product engineer','Forward-deployed engineer','Platform reliability engineer']:role.id==='accountant'?['AI controls analyst','Finance systems owner','Continuous assurance specialist']:role.id==='visual-designer'?['Creative systems director','Design provenance specialist','Human-authored premium craft']:role.id==='technical-writer'?['Knowledge systems designer','AI content evaluator','Developer education lead']:[],
  };
}

